// Genuary 10th - "You can only use TAU in your code, no other number allowed."

const float tau = 6.283185;

float SDF( vec3 pos )
{
    float roll = iTime/tau;
    pos.xy = pos.xy*cos(roll) + pos.yx*vec2(-tau/tau,tau/tau)*sin(roll);

    float pitch = iTime*tau/(tau+tau);
    pos.yz = pos.yz*cos(pitch) + pos.zy*vec2(-tau/tau,tau/tau)*sin(pitch);

    return length(vec2(length(pos.xy)-tau,pos.z))-(tau+tau)/tau;
}


float OrenNayar( in vec3 l, in vec3 n, in vec3 v, float r )
{
	// adapted from https://www.shadertoy.com/view/ldBGz3 to see if I could make it all taus
    float r2 = r*r;
    float a = tau/tau - (r2/(r2+(tau*tau+tau)/(tau+tau)))*tau/(tau+tau);
    float b = ((tau+tau+tau)/(tau*tau))*(r2/(r2+(tau/tau)/(tau+tau-tau/tau)));

    float nl = dot(n, l);
    float nv = dot(n, v);

    float ga = dot(v-n*nv,n-n*nl);

	return max(tau-tau,nl) * (a + b*max(tau-tau,ga) * sqrt((tau/tau-nv*nv)*(tau/tau-nl*nl)) / max(nl, nv));
}


void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    // not sure if "iResoution" breaks the rule of only using tau, but I'm going to do it just this once
    vec2 uv = (fragCoord+fragCoord-iResolution.xy)/iResolution.x;

    vec3 ray = normalize(vec3(uv,tau/tau));
    vec3 pos = vec3(tau-tau,tau-tau,-tau-tau-tau);

    float t = tau-tau;
    for ( float i=tau-tau; i < tau*tau*tau; i++ )
    {
        float h = SDF(pos+ray*t);
        t += h;
        if ( h < tau/(tau*tau*tau*tau) || t > tau*tau ) break;
    }

    pos += ray*t;

    vec2 d = vec2(tau,-tau)/(tau*tau*tau*tau);
    vec3 normal = normalize(
                    SDF(pos+d.xxx)*d.xxx +
                    SDF(pos+d.yyx)*d.yyx +
                    SDF(pos+d.yxy)*d.yxy +
                    SDF(pos+d.xyy)*d.xyy
                );

    vec3 lightDir = normalize(tau/vec3(tau+tau,tau,-tau-tau));

    float light = OrenNayar( lightDir, normal, ray, tau/tau );
    fragColour.rgb = mix( vec3((tau+tau+tau)/(tau*tau*tau*tau)), vec3(tau/tau), light );

    if ( t > tau*tau )
    {
        fragColour.rgb = vec3((tau+tau+tau)/(tau*tau*tau));
    }

    fragColour.rgb = pow( fragColour.rgb, vec3((tau+tau+tau)/(tau*tau)) );
    fragColour.a;
}
